/**
 * TravelWise AI+ Verified Destination & Attraction Catalog
 * Auto-synchronized with backend destination_data.py
 * Contains authentic Wikimedia Commons photography, accurate coordinates, and deduplication logic.
 */

export interface CatalogActivity {
  place_id: string;
  name: string;
  category: string;
  interests: string[];
  duration_hours: number;
  time_slot: string;
  estimated_entry_cost: number;
  estimated_transport_cost: number;
  opening_hours: string;
  weather_suitability: string;
  transit_time_mins: number;
  latitude?: number;
  longitude?: number;
  image_url: string;
  photo_attribution: string;
  source_url: string;
  verification_status: string;
  last_verified: string;
  description: string;
  reason: string;
  indoor: boolean;
  cost_tier: string;
}

export interface CatalogDestination {
  name: string;
  state_country: string;
  currency: string;
  latitude: number;
  longitude: number;
  hero_image: string;
  description: string;
  activities: CatalogActivity[];
}

export function normalizePlaceName(name: string): string {
  if (!name) return '';
  let s = name.toLowerCase().trim();
  s = s.replace(/[()[\]]/g, ' ');
  s = s.replace(/\b(visit|explore|tour|trip|viewpoint|view|scenic|walk|stroll|highlights?|the|and|point|hub|center|centre|monument|attraction|stop|unesco)\b/gi, ' ');
  s = s.replace(/[^a-z0-9]/gi, ' ');
  const tokens = Array.from(new Set(s.split(/\s+/).filter(t => t.length > 2))).sort();
  return tokens.join(' ');
}

export function arePlacesDuplicate(
  name1: string,
  name2: string,
  coord1?: [number | undefined, number | undefined],
  coord2?: [number | undefined, number | undefined],
  placeId1?: string,
  placeId2?: string
): boolean {
  if (placeId1 && placeId2 && placeId1 === placeId2) {
    return true;
  }

  const norm1 = normalizePlaceName(name1);
  const norm2 = normalizePlaceName(name2);
  if (!norm1 || !norm2) return false;
  if (norm1 === norm2) return true;

  const t1 = new Set(norm1.split(' ').filter(Boolean));
  const t2 = new Set(norm2.split(' ').filter(Boolean));
  if (t1.size === 0 || t2.size === 0) return false;

  // Check if shorter name tokens are a complete subset of longer name tokens
  // E.g. 'Fort Aguada' vs 'Fort Aguada & Lighthouse'
  const isSubset1 = Array.from(t1).every(tok => t2.has(tok));
  const isSubset2 = Array.from(t2).every(tok => t1.has(tok));
  if (isSubset1 || isSubset2) {
    const intersectionSize = Array.from(t1).filter(tok => t2.has(tok)).length;
    if (intersectionSize >= Math.min(t1.size, t2.size)) {
      return true;
    }
  }

  // Jaccard similarity
  const intersection = Array.from(t1).filter(tok => t2.has(tok)).length;
  const union = new Set([...Array.from(t1), ...Array.from(t2)]).size;
  const jaccard = intersection / union;
  if (jaccard >= 0.50) {
    return true;
  }

  // Proximity check if coordinates are provided
  if (coord1 && coord2 && coord1[0] !== undefined && coord2[0] !== undefined) {
    const latDiff = Math.abs((coord1[0] || 0) - (coord2[0] || 0));
    const lonDiff = Math.abs((coord1[1] || 0) - (coord2[1] || 0));
    if (latDiff < 0.0002 && lonDiff < 0.0002) {
      return true;
    }
    if (latDiff < 0.0025 && lonDiff < 0.0025 && intersection >= 1) {
      return true;
    }
  }

  return false;
}

