export function getDestinationData(query: string): CatalogDestination {
  if (!query) {
    return DESTINATIONS_CATALOG['munnar'] || Object.values(DESTINATIONS_CATALOG)[0];
  }

  const clean = query.trim().toLowerCase();

  // Direct key lookup
  if (DESTINATIONS_CATALOG[clean]) {
    return DESTINATIONS_CATALOG[clean];
  }

  // Alias lookup
  if (DESTINATION_ALIASES[clean] && DESTINATIONS_CATALOG[DESTINATION_ALIASES[clean]]) {
    return DESTINATIONS_CATALOG[DESTINATION_ALIASES[clean]];
  }

  // Match by display name
  for (const [key, dest] of Object.entries(DESTINATIONS_CATALOG)) {
    if (dest.name.toLowerCase() === clean) {
      return dest;
    }
  }

  // Match by substring (min 4 chars)
  for (const [key, dest] of Object.entries(DESTINATIONS_CATALOG)) {
    if (key.length >= 4 && (clean.includes(key) || key.includes(clean))) {
      return dest;
    }
    if (dest.name.length >= 4 && (clean.includes(dest.name.toLowerCase()) || dest.name.toLowerCase().includes(clean))) {
      return dest;
    }
  }

  // Fallback to first destination or Munnar
  return DESTINATIONS_CATALOG['munnar'] || Object.values(DESTINATIONS_CATALOG)[0];
}
